@page "/settings"
@using sv_72a46585c28747468775b3e6e3c9ecc6.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading">Loading...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (showRevokeConfirm)
        {
            <div class="modal-overlay" @onclick="CancelRevoke">
                <div class="modal" @onclick:stopPropagation="true">
                    <h3>Revoke Session</h3>
                    <p>Are you sure you want to revoke the session on <strong>@revokeTargetDevice</strong>? This will sign out that device immediately.</p>
                    <div class="modal-actions">
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                    </div>
                </div>
            </div>
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;

    // Toast
    private string? toastMessage;
    private string toastType = "success";
    private CancellationTokenSource? toastCts;

    // Profile
    private UserProfile? profile;
    private UserProfile? savedProfile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editBio = "";
    private string editAvatarUrl = "";

    // Notifications
    private NotificationPrefs? notificationPrefs;
    private bool editEmailNotifications;
    private bool editPushNotifications;
    private bool editWeeklyDigest;
    private List<string> allChannels = new() { "general", "marketing", "engineering", "design", "announcements" };
    private HashSet<string> mutedChannels = new();

    // Security
    private SecuritySettings? security;
    private bool showChangePassword;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool showRevokeConfirm;
    private string? revokeTargetId;
    private string? revokeTargetDevice;

    // Appearance
    private AppearanceSettings? appearance;
    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "English";
    private bool editCompactMode;
    private readonly List<string> languages = new() { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        isLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        switch (activeSection)
        {
            case "Profile":
                profile = await SettingsService.GetProfileAsync();
                savedProfile = profile;
                ResetProfileFields();
                break;
            case "Notifications":
                notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                editEmailNotifications = notificationPrefs.EmailNotifications;
                editPushNotifications = notificationPrefs.PushNotifications;
                editWeeklyDigest = notificationPrefs.WeeklyDigest;
                mutedChannels = new HashSet<string>(notificationPrefs.MutedChannels);
                break;
            case "Security":
                security = await SettingsService.GetSecuritySettingsAsync();
                showChangePassword = false;
                currentPassword = "";
                newPassword = "";
                confirmPassword = "";
                break;
            case "Appearance":
                appearance = await SettingsService.GetAppearanceAsync();
                editTheme = appearance.Theme;
                editFontSize = appearance.FontSize;
                editLanguage = appearance.Language;
                editCompactMode = appearance.CompactMode;
                break;
        }
        isLoading = false;
    }

    private void ResetProfileFields()
    {
        if (savedProfile is not null)
        {
            editDisplayName = savedProfile.DisplayName;
            editEmail = savedProfile.Email;
            editBio = savedProfile.Bio;
            editAvatarUrl = savedProfile.AvatarUrl;
        }
    }

    // Profile actions
    private async Task SaveProfile()
    {
        var updated = new UserProfile(editDisplayName, editEmail, editAvatarUrl, editBio);
        await SettingsService.SaveProfileAsync(updated);
        savedProfile = updated;
        profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        ResetProfileFields();
        ShowToast("Changes discarded.", "info");
    }

    // Notifications actions
    private void ToggleMutedChannel(string channel, ChangeEventArgs e)
    {
        if (e.Value is true)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(editEmailNotifications, editPushNotifications, editWeeklyDigest, mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        notificationPrefs = prefs;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security actions
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (newPassword != confirmPassword)
        {
            ShowToast("New passwords do not match.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showChangePassword = false;
        security = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "success");
    }

    private void RequestRevoke(string sessionId, string device)
    {
        revokeTargetId = sessionId;
        revokeTargetDevice = device;
        showRevokeConfirm = true;
    }

    private void CancelRevoke()
    {
        showRevokeConfirm = false;
        revokeTargetId = null;
        revokeTargetDevice = null;
    }

    private async Task ConfirmRevoke()
    {
        if (revokeTargetId is not null)
        {
            await SettingsService.RevokeSessionAsync(revokeTargetId);
            security = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        showRevokeConfirm = false;
        revokeTargetId = null;
        revokeTargetDevice = null;
    }

    // Appearance actions
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        appearance = settings;
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastCts?.Cancel();
        toastMessage = message;
        toastType = type;
        toastCts = new CancellationTokenSource();
        _ = AutoDismissToast(toastCts.Token);
    }

    private async Task AutoDismissToast(CancellationToken ct)
    {
        try
        {
            await Task.Delay(3000, ct);
            toastMessage = null;
            await InvokeAsync(StateHasChanged);
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        toastCts?.Cancel();
        toastMessage = null;
    }

    // Render helpers
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <div class="section-header">
            <h2>Profile Settings</h2>
            <p class="section-description">Manage your public profile information</p>
        </div>

        <div class="form-section">
            <div class="avatar-area">
                <div class="avatar-preview">
                    <img src="@editAvatarUrl" alt="Avatar" />
                </div>
                <div class="avatar-url">
                    <label>Avatar URL</label>
                    <input type="text" @bind="editAvatarUrl" placeholder="https://..." />
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="editDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="editEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="editBio"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <div class="section-header">
            <h2>Notification Preferences</h2>
            <p class="section-description">Choose how you want to be notified</p>
        </div>

        <div class="form-section">
            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="editEmailNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="editPushNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" @bind="editWeeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <div class="muted-channels">
                <h3>Muted Channels</h3>
                <p class="hint">Check channels you want to mute</p>
                @foreach (var channel in allChannels)
                {
                    <label class="checkbox-label">
                        <input type="checkbox"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="(e) => ToggleMutedChannel(channel, e)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <div class="section-header">
            <h2>Security</h2>
            <p class="section-description">Manage your account security settings</p>
        </div>

        <div class="form-section">
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => showChangePassword = !showChangePassword">
                    <span>Change Password</span>
                    <span class="expand-icon">@(showChangePassword ? "▼" : "▶")</span>
                </button>
                @if (showChangePassword)
                {
                    <div class="panel-content">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input type="password" @bind="currentPassword" />
                        </div>
                        <div class="form-group">
                            <label>New Password</label>
                            <input type="password" @bind="newPassword" />
                        </div>
                        <div class="form-group">
                            <label>Confirm New Password</label>
                            <input type="password" @bind="confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                        @if (security?.LastPasswordChange is not null)
                        {
                            <p class="hint">Last changed: @security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }
                    </div>
                }
            </div>

            <div class="two-factor-section">
                <h3>Two-Factor Authentication</h3>
                <div class="status-row">
                    <span class="status-indicator @(security?.TwoFactorEnabled == true ? "enabled" : "disabled")">
                        @(security?.TwoFactorEnabled == true ? "● Enabled" : "○ Disabled")
                    </span>
                </div>
            </div>

            <div class="sessions-section">
                <h3>Active Sessions</h3>
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (security?.Sessions is not null)
                        {
                            @foreach (var session in security.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != security.Sessions.First().Id)
                                        {
