                        @if (security?.LastPasswordChange is not null)
                        {
                            <p class="hint">Last changed: @security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }
                    </div>
                }
            </div>

            <div class="two-factor-section">
                <h3>Two-Factor Authentication</h3>
                <div class="status-row">
                    <span class="status-indicator @(security?.TwoFactorEnabled == true ? "enabled" : "disabled")">
                        @(security?.TwoFactorEnabled == true ? "● Enabled" : "○ Disabled")
                    </span>
                </div>
            </div>

            <div class="sessions-section">
                <h3>Active Sessions</h3>
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (security?.Sessions is not null)
                        {
                            @foreach (var session in security.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
