    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <div class="section-header">
            <h2>Appearance</h2>
            <p class="section-description">Customize the look and feel of the application</p>
        </div>

        <div class="form-section">
            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Light" @onchange='() => editTheme = "Light"' checked="@(editTheme == "Light")" /> Light
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Dark" @onchange='() => editTheme = "Dark"' checked="@(editTheme == "Dark")" /> Dark
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="System" @onchange='() => editTheme = "System"' checked="@(editTheme == "System")" /> System
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Small" @onchange='() => editFontSize = "Small"' checked="@(editFontSize == "Small")" /> Small
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Medium" @onchange='() => editFontSize = "Medium"' checked="@(editFontSize == "Medium")" /> Medium
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Large" @onchange='() => editFontSize = "Large"' checked="@(editFontSize == "Large")" /> Large
                    </label>
                </div>
            </div>

